// Server-side helpers for Ethora (generated by the ethora-skill). Node >= 18, no dependencies.
// Env: ETHORA_APP_ID, ETHORA_APP_SECRET, ETHORA_API_URL (default https://api.chat.ethora.com)
//
//   const { clientToken, ensureEthoraUser } = require('./ethora-token');
//   app.get('/api/ethora/token', requireAuth, async (req, res) => {
//     await ensureEthoraUser({ userId: req.user.id, email: req.user.email, firstName: req.user.firstName, lastName: req.user.lastName });
//     // only one name field? ensureEthoraUser({ userId, email, name: req.user.name }) — it is split and padded
//     res.json({ token: clientToken(req.user.id) });
//   });
const { createHmac } = require('node:crypto');

const APP_ID = process.env.ETHORA_APP_ID;
const APP_SECRET = process.env.ETHORA_APP_SECRET;
const API_URL = (process.env.ETHORA_API_URL || 'https://api.chat.ethora.com').replace(/\/v[12]\/?$/, '');

const b64url = (b) => Buffer.from(b).toString('base64').replace(/=/g, '').replace(/\+/g, '-').replace(/\//g, '_');
function sign(payload) {
  if (!APP_ID || !APP_SECRET) throw new Error('ETHORA_APP_ID / ETHORA_APP_SECRET are not set');
  const h = b64url(JSON.stringify({ alg: 'HS256', typ: 'JWT' }));
  const b = b64url(JSON.stringify(payload));
  return `${h}.${b}.${b64url(createHmac('sha256', APP_SECRET).update(`${h}.${b}`).digest())}`;
}
const now = () => Math.floor(Date.now() / 1000);

/** Client JWT for the chat component (`jwtLogin.token`). `userId` = YOUR stable id for the user. */
function clientToken(userId, { ttlSeconds = 60 * 60 * 12 } = {}) {
  return sign({ data: { type: 'client', appId: APP_ID, userId: String(userId) }, iat: now(), exp: now() + ttlSeconds });
}

/** Server JWT for server-to-server calls (x-custom-token). */
function serverToken({ ttlSeconds = 3600 } = {}) {
  return sign({ data: { type: 'server', appId: APP_ID }, iat: now(), exp: now() + ttlSeconds });
}

// /v1/users/batch rejects firstName/lastName that are empty or shorter than 2 characters (422 VALIDATION_ERROR).
// Apps often have one "name" field or none: split it, and fall back to a neutral placeholder.
function ethoraNames({ firstName, lastName, name }) {
  const ok = (s) => (typeof s === 'string' && s.trim().length >= 2 ? s.trim() : null);
  const [first, ...rest] = String(name || '').trim().split(/\s+/);
  return { firstName: ok(firstName) || ok(first) || 'User', lastName: ok(lastName) || ok(rest.join(' ')) || 'User' };
}

const ensured = new Set(); // per-process memo; persist a flag in your DB for real deployments
/** Create the user in the Ethora app once (POST /v1/users/batch). Idempotent; errors for "already exists" are ignored.
 *  Pass firstName/lastName, or a single `name` (it is split). */
async function ensureEthoraUser({ userId, email, firstName, lastName, name }) {
  const key = String(userId);
  if (ensured.has(key)) return;
  const res = await fetch(`${API_URL}/v1/users/batch`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'x-custom-token': serverToken() },
    body: JSON.stringify({ bypassEmailConfirmation: true, usersList: [{ uuid: key, email, ...ethoraNames({ firstName, lastName, name }) }] }),
  });
  if (!res.ok) {
    const text = await res.text();
    if (!/exist|already|duplicate/i.test(text)) throw new Error(`Ethora user sync failed: ${res.status} ${text.slice(0, 300)}`);
  }
  ensured.add(key);
}

/** Optional: create a room and add members (server side). chatId = your stable id for the room. */
async function ensureRoom({ chatId, title, members = [] }) {
  const headers = { 'Content-Type': 'application/json', 'x-custom-token': serverToken() };
  const r = await fetch(`${API_URL}/v1/chats`, { method: 'POST', headers, body: JSON.stringify({ title, uuid: String(chatId), type: 'group' }) });
  if (!r.ok && !/exist|already/i.test(await r.text())) throw new Error('Ethora room creation failed');
  if (members.length) {
    await fetch(`${API_URL}/v2/chats/users-access`, { method: 'POST', headers, body: JSON.stringify({ chatName: `${APP_ID}_${chatId}`, members: members.map(String) }) });
  }
  return `${APP_ID}_${chatId}`; // room JID local part; full JID = `${this}@conference.<xmppHost>`
}

module.exports = { clientToken, serverToken, ensureEthoraUser, ensureRoom };
